#!/usr/bin/env bash
set -euo pipefail

# Generated by dcli-bootc gen — edit modules/*.yaml instead
# Profile: kineticos-plus


# === removals: Remove unwanted preinstalled applications ===

dnf remove -y \
    dolphin \
    spectacle \
    konsole \
    kwrite

# === base: Base system packages and configuration ===

# pre script (base)
mkdir -p /var/opt
dnf5 -y copr enable theblackdon/dcli-bootc

# post script (base)
rm -f /opt
mv /var/opt /opt
systemctl enable --force bootc-fetch-apply-updates.timer

# === rpmfusion: enable RPMFusion free and nonfree repos (needed for vlc, mpv, steam, codecs) ===

# pre script (rpmfusion)
dnf install -y https://mirrors.rpmfusion.org/free/fedora/rpmfusion-free-release-$(rpm -E %fedora).noarch.rpm https://mirrors.rpmfusion.org/nonfree/fedora/rpmfusion-nonfree-release-$(rpm -E %fedora).noarch.rpm

# === terra: Terra repositories (mangohud, gamescope and other Terra packages come from these) ===
sed -i 's/enabled=0/enabled=1/' /etc/yum.repos.d/terra.repo
sed -i 's/enabled=0/enabled=1/' /etc/yum.repos.d/terra-extras.repo

# === cleanup ===
dnf clean all && rm -rf /var/cache/dnf/*
